css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: calc(var(--loader-size) * .68); height: var(--loader-size); position: relative; display: flex; flex-direction: column; align-items: center; justify-content: flex-end; padding-bottom: 36%; }
.loader::after { content: ''; position: absolute; bottom: 0; left: 26%; width: 48%; height: 40%; clip-path: polygon(0 0, 100% 0, 50% 100%); background: repeating-linear-gradient(48deg, color-mix(in srgb, #000 16%, var(--accent-2)) 0 calc(var(--loader-size) * .035), var(--accent-2) calc(var(--loader-size) * .035) calc(var(--loader-size) * .07)); }
.loader span { border-radius: 50%; animation: scoop calc(var(--loader-speed) * 3) cubic-bezier(.35, 1.5, .5, 1) infinite; }
.loader span:nth-child(1) { order: 3; width: 78%; height: calc(var(--loader-size) * .28); background: radial-gradient(circle at 36% 30%, color-mix(in srgb, #fff 34%, var(--accent)), var(--accent)); }
.loader span:nth-child(2) { order: 2; width: 68%; height: calc(var(--loader-size) * .245); margin-bottom: -8%; background: radial-gradient(circle at 36% 30%, color-mix(in srgb, #fff 40%, var(--accent-2)), var(--accent-2)); animation-delay: calc(var(--loader-speed) * .3); }
.loader span:nth-child(3) { order: 1; width: 56%; height: calc(var(--loader-size) * .2); margin-bottom: -7%; background: radial-gradient(circle at 36% 30%, #fff, color-mix(in srgb, #fff 55%, var(--accent))); animation-delay: calc(var(--loader-speed) * .6); }
@keyframes scoop { 0% { opacity: 0; transform: translateY(-58%) scale(.7); } 12% { opacity: 1; } 22% { transform: translateY(0) scale(1.08); } 30% { transform: translateY(0) scale(1); } 82% { opacity: 1; transform: translateY(0) scale(1); } 94%, 100% { opacity: 0; transform: translateY(0) scale(0); } }
